SELECT m.instante AS "time", m.sensor_id || ' (' || m.unidad || ')' AS metric, m.valor AS value
FROM medidas m JOIN estaciones s USING (station_id)
WHERE $__timeFilter(m.instante) AND s.proyecto_id = ${proyecto:sqlstring}
  AND m.station_id IN (${estacion:sqlstring}) AND m.magnitud = ${magnitud:sqlstring}
ORDER BY 1
